INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine HDD immer langsamer als eine SSD?', 2, '[{"text": "Ja", "correct": true, "because": "Mechanik vs. Flash-Speicher"}, {"text": "Nein", "correct": false, "because": "HDDs sind in Geschwindigkeit limitiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Medium wähle ich für schnelle Bootzeiten?', 3, '[{"text": "SSD", "correct": true, "because": "Hohe Lese-/Schreibgeschwindigkeit"}, {"text": "HDD", "correct": false, "because": "Langsamer durch Mechanik"}, {"text": "Hybridlaufwerk", "correct": false, "because": "Kompromiss, aber nicht optimal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen ein Speichermedium für Backups geeignet?', 5, '[{"text": "Hohe Kapazität", "correct": true, "because": "Große Datenmengen speichern"}, {"text": "Geringe Kosten pro GB", "correct": true, "because": "Wirtschaftlich sinnvoll"}, {"text": "Hohe Geschwindigkeit", "correct": false, "because": "Sekundär für Backups"}, {"text": "Kleine Bauform", "correct": false, "because": "Weniger relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) SSDs haben keine beweglichen Teile. b) HDDs sind teurer pro GB.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, HDDs sind günstiger"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines Speichers für eine Datenbank?', 4, '[{"text": "Lesegeschwindigkeit", "correct": false, "because": "Kritisch für Abfragen"}, {"text": "Schreibgeschwindigkeit", "correct": false, "because": "Wichtig für Updates"}, {"text": "Geräuschpegel", "correct": true, "because": "Irrelevant in Serverräumen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine SSD länger hält als eine HDD?', 2, '[{"text": "Nein", "correct": true, "because": "Begrenzte Schreibzyklen"}, {"text": "Ja", "correct": false, "because": "HDDs können mechanisch langlebiger sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Laufwerk nehme ich für große Videoarchive?', 3, '[{"text": "HDD", "correct": true, "because": "Kostengünstig bei hoher Kapazität"}, {"text": "SSD", "correct": false, "because": "Zu teuer pro GB"}, {"text": "Externes Flash", "correct": false, "because": "Kapazität begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine SSD gegenüber einer HDD?', 5, '[{"text": "Schnellere Zugriffszeiten", "correct": true, "because": "Keine Mechanik"}, {"text": "Geringerer Stromverbrauch", "correct": true, "because": "Effizienter Betrieb"}, {"text": "Höhere Kapazität", "correct": false, "because": "HDDs bieten mehr"}, {"text": "Günstiger Preis", "correct": false, "because": "SSDs sind teurer"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) SSDs sind empfindlicher als HDDs. b) HDDs sind besser für Dauerbetrieb. Stimmt das?', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "a) ist falsch, SSDs sind robuster"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Gaming-PC?', 4, '[{"text": "Hohe Lesegeschwindigkeit", "correct": false, "because": "Wichtig für Ladezeiten"}, {"text": "Gute Schreibleistung", "correct": false, "because": "Für Installationen relevant"}, {"text": "Maximale Kapazität", "correct": true, "because": "Spiele brauchen nicht Terabytes"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind SSDs immer die beste Wahl?', 2, '[{"text": "Nein", "correct": true, "because": "Kosten vs. Kapazität abwägen"}, {"text": "Ja", "correct": false, "because": "Nicht bei jedem Budget"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren sind für eine Serverfestplatte entscheidend?', 4, '[{"text": "Hohe Zuverlässigkeit", "correct": true, "because": "Dauerbetrieb nötig"}, {"text": "Große Kapazität", "correct": true, "because": "Datenmengen speichern"}, {"text": "Kleinste Bauform", "correct": false, "because": "Weniger wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass HDDs nur für alte Systeme taugen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Immer noch nützlich für Massenspeicher"}, {"text": "Ja", "correct": false, "because": "HDDs sind nicht veraltet"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Speicher für eine Workstation?', 3, '[{"text": "Schnelle Zugriffe", "correct": true, "because": "Effizienz bei Arbeit"}, {"text": "Maximale Kapazität", "correct": false, "because": "Sekundär"}, {"text": "Geringe Kosten", "correct": false, "because": "Leistung zählt mehr"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) SSDs nutzen Flash-Speicher. b) HDDs haben keine Latenz.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Mechanik hat Latenz"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine HDD?', 5, '[{"text": "Langsamere Geschwindigkeit", "correct": true, "because": "Mechanische Teile"}, {"text": "Höhere Ausfallrate", "correct": true, "because": "Bewegliche Komponenten"}, {"text": "Geringere Kapazität", "correct": false, "because": "HDDs bieten mehr"}, {"text": "Höherer Preis", "correct": false, "because": "HDDs sind günstiger"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Speicher für einen Thin Client unwichtig?', 3, '[{"text": "Geschwindigkeit", "correct": false, "because": "Für Basisaufgaben nötig"}, {"text": "Kapazität", "correct": false, "because": "Minimal nötig"}, {"text": "Extreme Langlebigkeit", "correct": true, "because": "Thin Clients sind einfach ersetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind SSDs teurer pro GB als HDDs?', 3, '[{"text": "Ja", "correct": true, "because": "Flash-Technologie kostet mehr"}, {"text": "Nein", "correct": false, "because": "HDDs sind günstiger"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine größere Kapazität die Geschwindigkeit beeinflusst?', 2, '[{"text": "Nein", "correct": true, "because": "Technologie entscheidet"}, {"text": "Ja", "correct": false, "because": "Kapazität unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Speichermedium wähle ich für eine Virtualisierungsumgebung?', 4, '[{"text": "SSD", "correct": true, "because": "Schnelle I/O für VMs"}, {"text": "HDD", "correct": false, "because": "Zu langsam für viele VMs"}, {"text": "Externes Laufwerk", "correct": false, "because": "Nicht performant genug"}]');
